-- Customers from New York or California
SELECT * FROM customers_view
{{b1}} state {{b2}} ('NY', 'CA');

-- Customers registered in 2025 or later
SELECT * FROM customers_view
WHERE {{b3}}(registration_date) >= 2025;

CREATE OR REPLACE TEMP VIEW customers_enriched AS
SELECT *,
  {{b1}}(' ', first_name, last_name) AS full_name,
  {{b2}}(registration_date) AS registration_year
FROM customers_view;

CREATE OR REPLACE TEMP VIEW orders_typed AS
SELECT *,
  {{b3}}(order_datetime AS {{b4}}) AS order_ts
FROM orders_view;

SELECT order_id, order_datetime, order_ts FROM orders_typed LIMIT 5;

SELECT state, {{b1}}(*) AS customer_count
FROM customers_view
GROUP BY {{b2}}
ORDER BY customer_count {{b3}}
